    public async Task<CrmPage<ActivityDto>> ListActivitiesAsync(TenantId tenant, Guid entity, Guid? actor, string? state, int page, int size, string? scope, CancellationToken ct) { page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); await using var s = await OpenAsync(tenant, ct); var st = string.IsNullOrWhiteSpace(state) ? null : state.Trim(); var mine = !string.Equals(scope, "all", StringComparison.OrdinalIgnoreCase); var count = new NpgsqlCommand("select count(*) from business_crm.crm_activity where tenant_id=$1 and legal_entity_id=$2 and ($3::text is null or state=$3) and ($4::boolean=false or owner_id=$5 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=business_crm.crm_activity.tenant_id and tm.legal_entity_id=business_crm.crm_activity.legal_entity_id and tm.user_id=$5 and tm.team_id in (select team_id from business_crm.opportunity where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.opportunity_id union select team_id from business_crm.lead where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.lead_id) and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date)))", s.Connection, s.Transaction); Add(count, tenant.Value, entity, Db(st), mine, Db(actor)); var total = Convert.ToInt32(await count.ExecuteScalarAsync(ct)); await using var c = new NpgsqlCommand("select id,legal_entity_id,lead_id,opportunity_id,party_id,type,subject,state,due_at,completed_at,outcome,notes,owner_id,version from business_crm.crm_activity where tenant_id=$1 and legal_entity_id=$2 and ($3::text is null or state=$3) and ($4::boolean=false or owner_id=$5 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=business_crm.crm_activity.tenant_id and tm.legal_entity_id=business_crm.crm_activity.legal_entity_id and tm.user_id=$5 and tm.team_id in (select team_id from business_crm.opportunity where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.opportunity_id union select team_id from business_crm.lead where tenant_id=business_crm.crm_activity.tenant_id and id=business_crm.crm_activity.lead_id) and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date))) order by due_at offset $6 limit $7", s.Connection, s.Transaction); Add(c, tenant.Value, entity, Db(st), mine, Db(actor), (page - 1) * size, size); var list = new List<ActivityDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(ReadActivity(r)); await r.CloseAsync(); await CommitAsync(s); return new(list, total, page, size); }

    public async Task<CrmPage<ActivityDto>> ListSellerActivitiesAsync(TenantId tenant, Guid entity, Guid? actor, string mode, bool allAuthorized, int page, int size, CancellationToken ct)
    {
        page = Math.Max(1, page); size = Math.Clamp(size, 1, 200); var mine = !allAuthorized;
        var predicate = mode switch
        {
            "home" => "a.state='Scheduled' and a.due_at < current_date + interval '1 day'",
            "attention" => "a.state='Scheduled' and (a.due_at < now() or o.health_status in ('AtRisk','Stale') or (o.status='Open' and o.expected_close_date < current_date))",
            _ => "a.state='Scheduled'"
        };
        await using var s = await OpenAsync(tenant, ct);
        var filter = "a.tenant_id=$1 and a.legal_entity_id=$2 and (not $3::boolean or a.owner_id=$4 or exists(select 1 from business_crm.crm_sales_team_member tm where tm.tenant_id=a.tenant_id and tm.legal_entity_id=a.legal_entity_id and tm.team_id=(select team_id from business_crm.opportunity where tenant_id=a.tenant_id and id=a.opportunity_id) and tm.user_id=$4 and tm.active_from <= current_date and (tm.active_to is null or tm.active_to >= current_date))) and " + predicate;
        await using var count = new NpgsqlCommand("select count(*) from business_crm.crm_activity a left join business_crm.opportunity o on o.tenant_id=a.tenant_id and o.legal_entity_id=a.legal_entity_id and o.id=a.opportunity_id where " + filter, s.Connection, s.Transaction); Add(count, tenant.Value, entity, mine, Db(actor)); var total = Convert.ToInt32(await count.ExecuteScalarAsync(ct));
        await using var c = new NpgsqlCommand("select a.id,a.legal_entity_id,a.lead_id,a.opportunity_id,a.party_id,a.type,a.subject,a.state,a.due_at,a.completed_at,a.outcome,a.notes,a.owner_id,a.version from business_crm.crm_activity a left join business_crm.opportunity o on o.tenant_id=a.tenant_id and o.legal_entity_id=a.legal_entity_id and o.id=a.opportunity_id where " + filter + " order by case when a.due_at < now() then 0 else 1 end,a.due_at,a.created_at offset $5 limit $6", s.Connection, s.Transaction); Add(c, tenant.Value, entity, mine, Db(actor), (page - 1) * size, size); var list = new List<ActivityDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) list.Add(ReadActivity(r)); await r.CloseAsync(); await CommitAsync(s); return new(list, total, page, size);
    }
    public async Task<ActivityDto> CompleteActivityAsync(TenantId tenant, Guid actor, Guid entity, Guid id, CompleteActivityRequest request, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct);
        await using var c = new NpgsqlCommand("update business_crm.crm_activity set state='Completed',completed_at=coalesce(completed_at,now()),outcome=coalesce($4,outcome),notes=coalesce($5,notes),version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$6 and state='Scheduled' returning id", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, id, Db(request.Outcome), Db(request.Notes), request.Version);
        if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.activity_already_completed");
        await CommitAsync(s);
        var activity = (await GetActivityAsync(tenant, entity, id, ct))!;
        if (activity.OpportunityId is not null)
        {
            await using var os = await OpenAsync(tenant, ct);
            await ExecuteAsync(os, "update business_crm.opportunity set last_activity_at=now(),updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3", ct, tenant.Value, entity, activity.OpportunityId.Value);
            await CommitAsync(os);
        }
        if (request.CreateNextAction && request.NextDueAt is not null && !string.IsNullOrWhiteSpace(request.NextSubject))
            await CreateActivityAsync(tenant, actor, new(entity, activity.LeadId, activity.OpportunityId, activity.PartyId, activity.Type, request.NextSubject, request.NextDueAt.Value, null, activity.OwnerId, $"next-{id:D}-{request.Version}"), ct);
        return activity;
    }
    public async Task<ActivityDto> CancelActivityAsync(TenantId tenant, Guid entity, Guid id, long version, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("update business_crm.crm_activity set state='Cancelled',version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$4 and state='Scheduled' returning id", s.Connection, s.Transaction); Add(c, tenant.Value, entity, id, version); if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.activity_conflict"); await CommitAsync(s); return (await GetActivityAsync(tenant, entity, id, ct))!; }

    public async Task<IReadOnlyList<PipelineDto>> ListPipelinesAsync(TenantId tenant, Guid entity, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select id,legal_entity_id,code,name,status,is_default,version from business_crm.crm_pipeline where tenant_id=$1 and legal_entity_id=$2 and status='Active' order by is_default desc,code", s.Connection, s.Transaction); Add(c, tenant.Value, entity); var rows = new List<(Guid Id, Guid Entity, string Code, string Name, string Status, bool IsDefault, long Version)>(); await using (var r = await c.ExecuteReaderAsync(ct)) { while (await r.ReadAsync(ct)) rows.Add((r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetString(3), r.GetString(4), r.GetBoolean(5), r.GetInt64(6))); } var list = new List<PipelineDto>(rows.Count); foreach (var row in rows) list.Add(new(row.Id, row.Entity, row.Code, row.Name, row.Status, row.IsDefault, row.Version, await ReadStagesAsync(s.Connection, s.Transaction, tenant, row.Id, ct))); await CommitAsync(s); return list; }
    public async Task<PipelineDto> CreatePipelineAsync(TenantId tenant, CreatePipelineRequest request, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); var id = Guid.CreateVersion7(); if (request.IsDefault) await ExecuteAsync(s, "update business_crm.crm_pipeline set is_default=false where tenant_id=$1 and legal_entity_id=$2", ct, tenant.Value, request.LegalEntityId); await ExecuteAsync(s, "insert into business_crm.crm_pipeline(tenant_id,id,legal_entity_id,code,name,is_default,created_at,updated_at) values($1,$2,$3,$4,$5,$6,now(),now())", ct, tenant.Value, id, request.LegalEntityId, request.Code.Trim().ToUpperInvariant(), request.Name.Trim(), request.IsDefault); await CommitAsync(s); return (await ListPipelinesAsync(tenant, request.LegalEntityId, ct)).Single(x => x.Id == id); }
    public async Task<PipelineStageDto> CreateStageAsync(TenantId tenant, Guid entity, Guid pipelineId, CreateStageRequest request, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); var id = Guid.CreateVersion7(); await ExecuteAsync(s, "insert into business_crm.crm_pipeline_stage(tenant_id,id,pipeline_id,legal_entity_id,name,sequence,probability,stale_after_days,is_won,is_lost,created_at) select $1,$2,id,$3,$4,$5,$6,$7,$8,$9,now() from business_crm.crm_pipeline where tenant_id=$1 and legal_entity_id=$3 and id=$10", ct, tenant.Value, id, entity, request.Name.Trim(), request.Sequence, request.Probability, request.StaleAfterDays, request.IsWon, request.IsLost, pipelineId); await CommitAsync(s); await using var read = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select id,pipeline_id,name,sequence,probability,stale_after_days,is_won,is_lost,status from business_crm.crm_pipeline_stage where tenant_id=$1 and legal_entity_id=$2 and id=$3", read.Connection, read.Transaction); Add(c, tenant.Value, entity, id); await using var r = await c.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) throw new CrmException("crm.pipeline_invalid"); var stage = ReadStage(r); await r.CloseAsync(); await CommitAsync(read); return stage; }
    public async Task<PipelineDto> UpdatePipelineAsync(TenantId tenant, Guid entity, Guid pipelineId, UpdatePipelineRequest request, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(request.Name)) throw new CrmException("crm.pipeline_invalid");
        await using var s = await OpenAsync(tenant, ct);
        if (request.IsDefault) await ExecuteAsync(s, "update business_crm.crm_pipeline set is_default=false where tenant_id=$1 and legal_entity_id=$2 and id<>$3", ct, tenant.Value, entity, pipelineId);
        await using var c = new NpgsqlCommand("update business_crm.crm_pipeline set name=$4,is_default=$5,version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3 and version=$6 returning id", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, pipelineId, request.Name.Trim(), request.IsDefault, request.Version);
        if (await c.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.pipeline_stale");
        await CommitAsync(s); return (await ListPipelinesAsync(tenant, entity, ct)).Single(x => x.Id == pipelineId);
    }
    public async Task<IReadOnlyList<PipelineStageDto>> ReorderStagesAsync(TenantId tenant, Guid entity, Guid pipelineId, ReorderStagesRequest request, CancellationToken ct)
    {
        if (request.StageIds.Count == 0 || request.StageIds.Distinct().Count() != request.StageIds.Count) throw new CrmException("crm.stage_order_invalid");
        await using var s = await OpenAsync(tenant, ct);
        await using var version = new NpgsqlCommand("select version from business_crm.crm_pipeline where tenant_id=$1 and legal_entity_id=$2 and id=$3 for update", s.Connection, s.Transaction);
        Add(version, tenant.Value, entity, pipelineId);
        var currentVersion = await version.ExecuteScalarAsync(ct);
        if (currentVersion is null || Convert.ToInt64(currentVersion) != request.Version) throw new CrmException("crm.pipeline_stale");
        await using var validate = new NpgsqlCommand("select count(*) as total, count(*) filter (where id = any($4)) as matched from business_crm.crm_pipeline_stage where tenant_id=$1 and legal_entity_id=$2 and pipeline_id=$3 and status='Active'", s.Connection, s.Transaction);
        validate.Parameters.AddWithValue(tenant.Value); validate.Parameters.AddWithValue(entity); validate.Parameters.AddWithValue(pipelineId); validate.Parameters.AddWithValue(NpgsqlTypes.NpgsqlDbType.Array | NpgsqlTypes.NpgsqlDbType.Uuid, request.StageIds.ToArray());
        await using (var vr = await validate.ExecuteReaderAsync(ct))
        {
            await vr.ReadAsync(ct);
            if (vr.GetInt64(0) != request.StageIds.Count || vr.GetInt64(1) != request.StageIds.Count) throw new CrmException("crm.stage_order_invalid");
        }
        for (var i = 0; i < request.StageIds.Count; i++) { await using var set = new NpgsqlCommand("update business_crm.crm_pipeline_stage set sequence=$4 where tenant_id=$1 and legal_entity_id=$2 and pipeline_id=$3 and id=$5", s.Connection, s.Transaction); Add(set, tenant.Value, entity, pipelineId, 1000 + i, request.StageIds[i]); await set.ExecuteNonQueryAsync(ct); }
        for (var i = 0; i < request.StageIds.Count; i++) { await using var set = new NpgsqlCommand("update business_crm.crm_pipeline_stage set sequence=$4 where tenant_id=$1 and legal_entity_id=$2 and pipeline_id=$3 and id=$5", s.Connection, s.Transaction); Add(set, tenant.Value, entity, pipelineId, i + 1, request.StageIds[i]); await set.ExecuteNonQueryAsync(ct); }
        await using var bump = new NpgsqlCommand("update business_crm.crm_pipeline set version=version+1,updated_at=now() where tenant_id=$1 and legal_entity_id=$2 and id=$3", s.Connection, s.Transaction); Add(bump, tenant.Value, entity, pipelineId); await bump.ExecuteNonQueryAsync(ct); await CommitAsync(s); return (await ListPipelinesAsync(tenant, entity, ct)).Single(x => x.Id == pipelineId).Stages;
    }

    public async Task<ForecastDto> ForecastAsync(TenantId tenant, Guid entity, DateOnly? from, DateOnly? to, string currency, CancellationToken ct) { await using var s = await OpenAsync(tenant, ct); var start = from ?? DateOnly.MinValue; var end = to ?? DateOnly.MaxValue; await using var c = new NpgsqlCommand("select coalesce(sum(estimated_amount),0),coalesce(sum(estimated_amount*coalesce(st.probability,0)),0),coalesce(sum(o.estimated_amount) filter(where o.forecast_category='BestCase'),0),coalesce(sum(o.estimated_amount) filter(where o.forecast_category='Commit'),0),coalesce(sum(o.estimated_amount) filter(where o.status='Won'),0),count(*) filter(where o.status='Open'),count(*) filter(where o.status='Open' and (now() - coalesce(o.last_activity_at, o.updated_at, o.created_at) > (coalesce(st.stale_after_days, 14) || ' days')::interval or (o.expected_close_date is not null and o.expected_close_date < current_date))),count(*) filter(where o.status='Open' and o.expected_close_date is not null and o.expected_close_date < current_date) from business_crm.opportunity o join business_crm.crm_pipeline_stage st on st.tenant_id=o.tenant_id and st.id=o.stage_id where o.tenant_id=$1 and o.legal_entity_id=$2 and rtrim(o.currency_code)=$3 and (o.expected_close_date is null or o.expected_close_date between $4 and $5)", s.Connection, s.Transaction); Add(c, tenant.Value, entity, currency.Trim().ToUpperInvariant(), start, end); await using var r = await c.ExecuteReaderAsync(ct); await r.ReadAsync(ct); var result = new ForecastDto(r.GetDecimal(0), r.GetDecimal(1), r.GetDecimal(2), r.GetDecimal(3), r.GetDecimal(4), r.GetInt64(5) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(5), r.GetInt64(6) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(6), r.GetInt64(7) > int.MaxValue ? int.MaxValue : (int)r.GetInt64(7), currency.Trim().ToUpperInvariant()); await r.CloseAsync(); await CommitAsync(s); return result; }
    public async Task<CrmReportDto> ReportAsync(TenantId tenant, Guid entity, Guid? actor, string currency, CancellationToken ct)
    {
        var code = currency.Trim().ToUpperInvariant(); await using var s = await OpenAsync(tenant, ct);
        await using var leads = new NpgsqlCommand("select count(*),count(*) filter(where status='Qualified'),count(*) filter(where status='Converted'),count(*) filter(where status='Disqualified') from business_crm.lead where tenant_id=$1 and legal_entity_id=$2 and ($3::uuid is null or owner_id=$3)", s.Connection, s.Transaction); Add(leads, tenant.Value, entity, Db(actor));
        await using var lr = await leads.ExecuteReaderAsync(ct); await lr.ReadAsync(ct); var leadCount = (int)Math.Min(int.MaxValue, lr.GetInt64(0)); var qualified = (int)Math.Min(int.MaxValue, lr.GetInt64(1)); var converted = (int)Math.Min(int.MaxValue, lr.GetInt64(2)); var disqualified = (int)Math.Min(int.MaxValue, lr.GetInt64(3)); await lr.CloseAsync();
        await using var opportunities = new NpgsqlCommand("select count(*) filter(where o.status='Open'),count(*) filter(where o.status='Won'),count(*) filter(where o.status='Lost'),coalesce(sum(o.estimated_amount) filter(where o.status='Won'),0),coalesce(sum(o.estimated_amount) filter(where o.status='Lost'),0),count(*) filter(where o.status='Open' and (now() - coalesce(o.last_activity_at, o.updated_at, o.created_at) > (coalesce(st.stale_after_days, 14) || ' days')::interval or (o.expected_close_date is not null and o.expected_close_date < current_date))) from business_crm.opportunity o join business_crm.crm_pipeline_stage st on st.tenant_id=o.tenant_id and st.id=o.stage_id where o.tenant_id=$1 and o.legal_entity_id=$2 and rtrim(o.currency_code)=$3 and ($4::uuid is null or o.owner_id=$4)", s.Connection, s.Transaction); Add(opportunities, tenant.Value, entity, code, Db(actor));
        await using var or = await opportunities.ExecuteReaderAsync(ct); await or.ReadAsync(ct);
        var openCount = (int)Math.Min(int.MaxValue, or.GetInt64(0));
        var wonCount = (int)Math.Min(int.MaxValue, or.GetInt64(1));
        var lostCount = (int)Math.Min(int.MaxValue, or.GetInt64(2));
        var closedCount = wonCount + lostCount;
        var winRate = closedCount == 0 ? 0m : decimal.Round((decimal)wonCount / closedCount * 100, 2);
        var conversionRate = leadCount == 0 ? 0m : decimal.Round((decimal)converted / leadCount * 100, 2);
        var result = new CrmReportDto(leadCount, qualified, converted, disqualified, conversionRate, openCount, wonCount, lostCount, or.GetDecimal(3), or.GetDecimal(4), (int)Math.Min(int.MaxValue, or.GetInt64(5)), code, winRate);
        await or.CloseAsync(); await CommitAsync(s); return result;
    }
