            result.Add(new(opportunityId, interestId, reader.GetGuid(2), reader.GetGuid(3), reader.GetFieldValue<DateOnly>(4), reader.GetDecimal(5), reader.GetString(6), "CrmWonOpportunity", $"CrmOpportunity:{opportunityId:D}:{interestId:D}"));
        }
        await reader.CloseAsync();
        await CommitAsync(s);
        return result;
    }
