        var from = request.ActiveFrom ?? DateOnly.FromDateTime(DateTime.UtcNow.Date);
        await using var c = new NpgsqlCommand("insert into business_crm.crm_sales_team_member(tenant_id,id,legal_entity_id,team_id,user_id,role,active_from) select $1,$2,legal_entity_id,$3,$4,$5,$6 from business_crm.crm_sales_team where tenant_id=$1 and legal_entity_id=$7 and id=$3 returning team_id,user_id,role,active_from,active_to", s.Connection, s.Transaction);
        Add(c, tenant.Value, Guid.CreateVersion7(), teamId, request.UserId, request.Role.Trim(), from, entity);
        await using var r = await c.ExecuteReaderAsync(ct);
        if (!await r.ReadAsync(ct)) throw new CrmException("crm.team_not_found");
        var member = new TeamMemberDto(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetFieldValue<DateOnly>(3), r.IsDBNull(4) ? null : r.GetFieldValue<DateOnly>(4));
        await r.CloseAsync(); await CommitAsync(s); return member;
    }

    public async Task EndTeamMemberAsync(TenantId tenant, Guid entity, Guid teamId, Guid userId, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct);
        await using var c = new NpgsqlCommand("update business_crm.crm_sales_team_member set active_to=current_date where tenant_id=$1 and legal_entity_id=$2 and team_id=$3 and user_id=$4 and active_to is null", s.Connection, s.Transaction);
        Add(c, tenant.Value, entity, teamId, userId); await c.ExecuteNonQueryAsync(ct); await CommitAsync(s);
    }

    public async Task<IReadOnlyList<CustomFieldDefinitionDto>> ListCustomFieldDefinitionsAsync(TenantId tenant, Guid entity, string entityType, CancellationToken ct)
    {
        await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select id,legal_entity_id,entity_type,field_key,label,data_type,required_stage_id,status,version from business_crm.crm_custom_field_definition where tenant_id=$1 and legal_entity_id=$2 and entity_type=$3 and status='Active' order by field_key", s.Connection, s.Transaction); Add(c, tenant.Value, entity, entityType); var result = new List<CustomFieldDefinitionDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) result.Add(new(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetString(3), r.GetString(4), r.GetString(5), GuidValue(r, 6), r.GetString(7), r.GetInt64(8))); await r.CloseAsync(); await CommitAsync(s); return result;
    }

    public async Task<CustomFieldDefinitionDto> CreateCustomFieldDefinitionAsync(TenantId tenant, CreateCustomFieldDefinitionRequest request, CancellationToken ct)
    {
        if (request.EntityType is not ("Lead" or "Opportunity") || request.DataType is not ("Text" or "Integer" or "Decimal" or "Boolean" or "Date") || string.IsNullOrWhiteSpace(request.FieldKey) || (request.EntityType == "Lead" && request.RequiredStageId is not null)) throw new CrmException("crm.custom_field_definition_invalid");
        await using var s = await OpenAsync(tenant, ct);
        if (request.RequiredStageId is Guid requiredStage) { await using var stage = new NpgsqlCommand("select 1 from business_crm.crm_pipeline_stage where tenant_id=$1 and legal_entity_id=$2 and id=$3 and status='Active'", s.Connection, s.Transaction); Add(stage, tenant.Value, request.LegalEntityId, requiredStage); if (await stage.ExecuteScalarAsync(ct) is null) throw new CrmException("crm.custom_field_stage_not_found"); }
        var id = Guid.CreateVersion7(); await using var c = new NpgsqlCommand("insert into business_crm.crm_custom_field_definition(tenant_id,id,legal_entity_id,entity_type,field_key,label,data_type,required_stage_id) values($1,$2,$3,$4,$5,$6,$7,$8) returning id", s.Connection, s.Transaction); Add(c, tenant.Value, id, request.LegalEntityId, request.EntityType, request.FieldKey.Trim(), request.Label.Trim(), request.DataType, Db(request.RequiredStageId)); await c.ExecuteScalarAsync(ct); await CommitAsync(s); return (await ListCustomFieldDefinitionsAsync(tenant, request.LegalEntityId, request.EntityType, ct)).Single(x => x.Id == id);
    }

    public async Task<IReadOnlyList<CustomFieldValueDto>> SetCustomFieldValuesAsync(TenantId tenant, Guid actor, Guid entity, SetCustomFieldValueRequest request, CancellationToken ct)
    {
        if (request.EntityType is not ("Lead" or "Opportunity")) throw new CrmException("crm.custom_field_entity_invalid");
        await using var s = await OpenAsync(tenant, ct);
        Guid? stageId = null;
        if (request.EntityType == "Opportunity") { await using var stage = new NpgsqlCommand("select stage_id from business_crm.opportunity where tenant_id=$1 and legal_entity_id=$2 and id=$3", s.Connection, s.Transaction); Add(stage, tenant.Value, entity, request.EntityId); var stageValue = await stage.ExecuteScalarAsync(ct); stageId = stageValue is Guid value ? value : null; if (stageId is null) throw new CrmException("crm.opportunity_not_found"); }
        await using var definitions = new NpgsqlCommand("select id,field_key,data_type,required_stage_id from business_crm.crm_custom_field_definition where tenant_id=$1 and legal_entity_id=$2 and entity_type=$3 and status='Active'", s.Connection, s.Transaction); Add(definitions, tenant.Value, entity, request.EntityType); var defs = new Dictionary<string, (Guid Id, string Type, Guid? RequiredStage)>(StringComparer.OrdinalIgnoreCase); await using (var dr = await definitions.ExecuteReaderAsync(ct)) { while (await dr.ReadAsync(ct)) defs[dr.GetString(1)] = (dr.GetGuid(0), dr.GetString(2), GuidValue(dr, 3)); }
        foreach (var key in request.Values.Keys) { if (!defs.TryGetValue(key, out var definition)) throw new CrmException("crm.custom_field_unknown"); ValidateValue(definition.Type, request.Values[key]); }
        foreach (var pair in defs.Where(x => x.Value.RequiredStage is Guid required && required == stageId)) if (!request.Values.Keys.Any(x => string.Equals(x, pair.Key, StringComparison.OrdinalIgnoreCase))) throw new CrmException("crm.custom_field_required");
        foreach (var value in request.Values) { var definition = defs[value.Key]; await using var upsert = new NpgsqlCommand("insert into business_crm.crm_custom_field_value(tenant_id,id,legal_entity_id,entity_type,entity_id,field_id,value,version,updated_at) values($1,$2,$3,$4,$5,$6,$7::jsonb,1,now()) on conflict(tenant_id,entity_type,entity_id,field_id) do update set value=excluded.value,version=business_crm.crm_custom_field_value.version+1,updated_at=now()", s.Connection, s.Transaction); Add(upsert, tenant.Value, Guid.CreateVersion7(), entity, request.EntityType, request.EntityId, definition.Id, value.Value.GetRawText()); await upsert.ExecuteNonQueryAsync(ct); }
        await CommitAsync(s); return await ListCustomFieldValuesAsync(tenant, entity, request.EntityType, request.EntityId, ct);
    }

    public async Task<IReadOnlyList<CustomFieldValueDto>> ListCustomFieldValuesAsync(TenantId tenant, Guid entity, string entityType, Guid entityId, CancellationToken ct)
    { await using var s = await OpenAsync(tenant, ct); await using var c = new NpgsqlCommand("select d.field_key,d.data_type,v.value::text,v.version from business_crm.crm_custom_field_value v join business_crm.crm_custom_field_definition d on d.tenant_id=v.tenant_id and d.id=v.field_id where v.tenant_id=$1 and v.legal_entity_id=$2 and v.entity_type=$3 and v.entity_id=$4 order by d.field_key", s.Connection, s.Transaction); Add(c, tenant.Value, entity, entityType, entityId); var result = new List<CustomFieldValueDto>(); await using var r = await c.ExecuteReaderAsync(ct); while (await r.ReadAsync(ct)) result.Add(new(r.GetString(0), r.GetString(1), JsonDocument.Parse(r.GetString(2)).RootElement.Clone(), r.GetInt64(3))); await r.CloseAsync(); await CommitAsync(s); return result; }
    private static void ValidateValue(string type, System.Text.Json.JsonElement value) { var valid = type switch { "Text" => value.ValueKind == JsonValueKind.String, "Integer" => value.ValueKind == JsonValueKind.Number && value.TryGetInt64(out _), "Decimal" => value.ValueKind == JsonValueKind.Number && value.TryGetDecimal(out _), "Boolean" => value.ValueKind is JsonValueKind.True or JsonValueKind.False, "Date" => value.ValueKind == JsonValueKind.String && DateOnly.TryParse(value.GetString(), out _), _ => false }; if (!valid) throw new CrmException("crm.custom_field_type_invalid"); }
}
